import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const output = path.resolve(process.argv[2] ?? path.join(root, "build", "stage6-release"));
await mkdir(output, { recursive: true });
const digest = async file => createHash("sha256").update(await readFile(file)).digest("hex");
const materials = [".java-version", ".node-version", "gradle/wrapper/gradle-wrapper.properties", "pnpm-lock.yaml"];
const statement = {
  _type: "https://in-toto.io/Statement/v1",
  subject: [{ name: "ji-internal-rc", digest: { sha256: await digest(path.join(root, "pnpm-lock.yaml")) } }],
  predicateType: "https://slsa.dev/provenance/v1",
  predicate: {
    buildDefinition: { buildType: "https://ji.invalid/build/stage6", externalParameters: { publicRelease: false },
      resolvedDependencies: await Promise.all(materials.map(async name => ({ uri: name, digest: { sha256: await digest(path.join(root, name)) } }))) },
    runDetails: { builder: { id: "ji-local-stage6" }, metadata: {
      invocationId: execFileSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8" }).trim(),
      startedOn: new Date().toISOString(),
    } },
  },
};
await writeFile(path.join(output, "provenance.intoto.jsonl"), `${JSON.stringify(statement)}\n`);
process.stdout.write(`${path.join(output, "provenance.intoto.jsonl")}\n`);
